// The two things the caller needs out of the model's answer: the H1, which the row
// stores as ARTICLE_TITLE and the entry point turns into the frozen slug, and the body,
// which carries one `<!-- asset:<type> -->` marker per requested asset. The word budget
// is checked here rather than trusted to the model: a mandatory count in a format is a
// count that gets invented when the real one is missing.
//
// A problem is reported as data (`PROBLEM`), never thrown: a draft that ran long or came
// back without a title is retried by the review loop below, and only a run that exhausts
// its attempts reports the reason to the caller.
//
// MAX_WORDS is required. The entry point resolves the row's budget and the 1200 default,
// so a value missing here is a caller bug: fail loudly rather than guess a bound.
const req = $('set_workflow_vars').first().json;
const max = Number(req.MAX_WORDS);
if (!isFinite(max) || max <= 0) throw new Error('MAX_WORDS is required and must be a positive number');
// An agent node answers `output` where a chain node answered `text`; the sub-workflow's
// own contract stays the old names, so this is the one place the difference is absorbed.
const raw = String($json.output || $json.text || '');
const block = /<article>([\s\S]*?)<\/article>/.exec(raw);
const inner = (block ? block[1] : raw).trim();
const HEAD = /^#\s+(.+?)\s*$/;
let title = '';
const body = [];
for (const line of inner.split('\n')) {
  if (!title && !body.length && HEAD.test(line.trim())) {
    title = line.trim().replace(HEAD, '$1');
    continue;
  }
  body.push(line);
}
const text = body.join('\n').trim();
// A marker is an instruction to the publishing step, not prose the reader counts.
const words = text.replace(/<!--[\s\S]*?-->/g, ' ').split(/\s+/).filter(Boolean).length;
// The marker set is counted here rather than trusted to the review: how many markers a draft
// carries is a count, and a count a model is asked for is a count it misses. Both drafts of
// execution 14228 carried the same marker twice, the gate passed them, and the article ended up
// referencing one illustration twice.
const requested = String($('main_trigger').first().json.ASSET_TYPES || '')
  .split(',').map((s) => s.trim()).filter(Boolean);
const markers = (text.match(/<!--\s*asset:[a-zA-Z0-9_]+\s*-->/g) || [])
  .map((m) => m.replace('<!--', '').replace('-->', '').replace('asset:', '').trim());
const wrongMarkers = [
  ...requested.filter((t) => markers.filter((m) => m === t).length !== 1)
    .map((t) => t + ' x' + markers.filter((m) => m === t).length),
  ...markers.filter((m) => !requested.includes(m)).map((m) => m + ' not requested'),
];
let problem = '';
if (!text) problem = 'EMPTY_DRAFT: the model returned no article body';
else if (!title) problem = 'EMPTY_TITLE: the draft has no H1 title';
else if (words > max) problem = 'OVER_BUDGET: ' + words + ' words against MAX_WORDS=' + max;
else if (wrongMarkers.length) problem = 'MARKERS: ' + wrongMarkers.join(', ');
return { json: { TITLE: title, TEXT: text, WORD_COUNT: words, MAX_WORDS: max, PROBLEM: problem } };

// The verdict the loop branches on. The reviewer's answer is combined with the parser's
// deterministic checks, and the deterministic half wins: a count asked of a model is a
// count that gets invented, so `PROBLEM` rejects the draft whatever the reviewer said —
// and the reason then names the real numbers rather than the reviewer's guess.
const parsed = $('parse_article').item.json;
const reviewerSays = String($json.output || '').trim() === 'true';
const reason = String($json.explanation || '').replace(/\s+/g, ' ').trim();
const problem = String(parsed.PROBLEM || '');

const accepted = !problem && reviewerSays;
let explanation = '';
if (problem) explanation = problem + (reason ? ' ' + reason : '');
else if (!reviewerSays) explanation = reason || 'the reviewer rejected the draft without a reason';

return [{ json: { ...$json, output: accepted ? 'true' : 'false', explanation } }];

// The reviewer answers one verdict per draft as `<output>true|false</output>` and a short
// `<explanation>`. The explanation is flattened to one line because it has two readers: the
// next attempt's Reviewer Feedback block and the `MAX_RETRIES_EXCEEDED` report.
for (const item of $input.all()) {
  const { text } = item.json;

  const output = text.includes('<output>') && text.includes('</output>')
    ? text.split('<output>')[1].split('</output>')[0].trim().toLowerCase()
    : 'false';

  const explanation = text.includes('<explanation>') && text.includes('</explanation>')
    ? text.split('<explanation>')[1].split('</explanation>')[0].replace(/\s+/g, ' ').trim()
    : '';

  item.json.output = output;
  item.json.explanation = explanation;
}

return $input.all();

// prompts/article_tools.md is the one copy of the two tool descriptions. A missing
// section fails the run: a tool with no description is a capability the model cannot use.
const text = String($json.output || '');
const section = (name) => {
  const lines = text.split('\n');
  const start = lines.findIndex((l) => l.trim() === '## ' + name);
  if (start < 0) return '';
  const out = [];
  for (let i = start + 1; i < lines.length; i++) {
    if (lines[i].trim().startsWith('## ')) break;
    out.push(lines[i]);
  }
  return out.join('\n').trim();
};
const out = { RESEARCH_SOURCES: section('research_sources'), READ_PAGE: section('read_page') };
for (const [k, v] of Object.entries(out)) {
  if (!v) throw new Error('prompts/article_tools.md carries no ' + k + ' section');
}
return [{ json: out }];

